  `maiden_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `birth_date` date DEFAULT NULL,
  `military_service` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `martial_status` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `children_number` int(10) unsigned DEFAULT NULL,
  `mobile_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `office_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `personal_address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `personal_address_2` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `personal_zip_code` int(10) unsigned DEFAULT NULL,
  `personal_city` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `personal_country` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `secu_social` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `secu_social_key` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `society_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `society_address` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `society_address_2` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `society_zip_code` int(10) unsigned DEFAULT NULL,
  `society_city` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `society_country` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` longtext COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `comments` longtext COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_id` int(11) NOT NULL,
  `parent_id` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC;
